//! Compiles the icon and version information into `windup.exe`.
//!
//! `ViewportBuilder::with_icon` only reaches the running windows. Explorer's
//! icon on the file, the Start menu shortcut, a pinned taskbar button before
//! launch, and the name Task Manager shows all come from resources in the
//! executable, which is what this adds. The `.ico` is generated by
//! `cargo run -p windup-ui --example make-art`.
//!
//! Other platforms have no equivalent at build time: Linux takes its icon from
//! the desktop entry and macOS from the `.app` bundle's `Info.plist`, both of
//! which are packaging (`packaging/<os>/`), not compilation.

use std::path::{Path, PathBuf};

fn main() {
    let manifest = std::env::var_os("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR");
    let icon = PathBuf::from(manifest).join("../../assets/icons/windup.ico");
    println!("cargo::rerun-if-changed={}", icon.display());
    println!("cargo::rerun-if-changed=build.rs");
    embed(&icon);
}

/// Gated on the host, because Cargo resolves `[target.….build-dependencies]`
/// against the host triple. `winresource` itself does nothing when the target
/// is not Windows.
#[cfg(windows)]
fn embed(icon: &Path) {
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }
    let version = std::env::var("CARGO_PKG_VERSION").expect("CARGO_PKG_VERSION");
    let mut res = winresource::WindowsResource::new();
    if icon.exists() {
        res.set_icon(&icon.to_string_lossy());
    } else {
        println!(
            "cargo::warning=no {}; the executable will have the default icon",
            icon.display()
        );
    }
    res.set("ProductName", "Windup")
        .set("FileDescription", "Windup")
        .set("CompanyName", "Spillebulle")
        .set("LegalCopyright", "GPL-3.0-or-later")
        .set("OriginalFilename", "windup.exe")
        .set("InternalName", "windup")
        .set("ProductVersion", &version)
        .set("FileVersion", &version);

    // The resource compiler ships with the Windows SDK. A machine without it
    // can still build and run Windup, so this warns rather than failing; CI
    // always has the SDK, so there it is an error: a release without its icon
    // is the thing this file exists to prevent.
    if let Err(e) = res.compile() {
        if std::env::var_os("CI").is_some() {
            panic!("could not embed the Windows resources: {e}");
        }
        println!("cargo::warning=could not embed the Windows resources: {e}");
    }
}

#[cfg(not(windows))]
fn embed(_icon: &Path) {}
